import { ValidationError } from "../domain/errors";
import { IdGenerator } from "../domain/id-generator";
import { Order } from "../domain/order";
import { OrderItem } from "../domain/order-item";
import { OrderRepository } from "../domain/order-repository";
import { StockReservationService } from "../domain/stock-reservation-service";
import { OrderDto, PlaceOrderRequest, toOrderDto } from "./dtos";

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly reservations: StockReservationService,
    private readonly ids: IdGenerator,
  ) {}

  async execute(request: PlaceOrderRequest): Promise<OrderDto> {
    const { customerId, items } = request;
    if (typeof customerId !== "string" || customerId.trim() === "") {
      throw new ValidationError("customerId is required");
    }
    if (!Array.isArray(items) || items.length === 0) {
      throw new ValidationError("items must be a non-empty array");
    }
    const orderItems = items.map((raw: unknown) => {
      const entry = (raw ?? {}) as { productId?: unknown; quantity?: unknown };
      if (typeof entry.productId !== "string" || entry.productId === "") {
        throw new ValidationError("productId is required");
      }
      return new OrderItem(entry.productId, entry.quantity as number);
    });
    await this.reservations.reserve(orderItems);
    const order = new Order(this.ids.next(), customerId, orderItems, new Date());
    await this.orders.save(order);
    return toOrderDto(order);
  }
}

